import java.io.File;
import java.nio.file.Path;
import java.nio.file.Paths;

public class ImportingUtilities {

    // other methods

    static public File allocateFile(File dir, String name) {
        // Remove query parameters if present
        int q = name.indexOf('?');
        if (q > 0) {
            name = name.substring(0, q);
        }

        // Resolve the target file path
        Path dirPath = dir.toPath().normalize();
        Path targetPath = dirPath.resolve(name).normalize();

        // Ensure the target path is within the intended directory
        if (!targetPath.startsWith(dirPath)) {
            throw new IllegalArgumentException(
                "Invalid file name: " + name + ". It resolves outside the target directory."
            );
        }

        // Construct the File object from the validated path
        File file = targetPath.toFile();

        // Determine prefix and suffix for duplicate handling
        int dot = name.lastIndexOf('.');
        String prefix = dot < 0 ? name : name.substring(0, dot);
        String suffix = dot < 0 ? "" : name.substring(dot);

        int index = 2;
        while (file.exists()) {
            // Append an incrementing suffix until a unique filename is found
            String newName = prefix + "-" + index++ + suffix;
            targetPath = dirPath.resolve(newName).normalize();
            if (!targetPath.startsWith(dirPath)) {
                throw new IllegalArgumentException(
                    "Duplicate file name resolution attempted to escape the target directory."
                );
            }
            file = targetPath.toFile();
        }

        // Create parent directories if they do not exist
        File parent = file.getParentFile();
        if (parent != null && !parent.exists()) {
            if (!parent.mkdirs() && !parent.isDirectory()) {
                throw new RuntimeException("Failed to create directories: " + parent);
            }
        }

        return file;
    }

    // other methods

}
