import java.io.FileOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Date;
import org.codehaus.plexus.archiver.util.ArchiveEntryUtils;
import org.codehaus.plexus.components.io.attributes.SymlinkUtils;
import org.codehaus.plexus.logging.AbstractLogEnabled;
import org.codehaus.plexus.util.FileUtils;
import org.codehaus.plexus.util.IOUtil;
import org.codehaus.plexus.util.StringUtils;

public abstract class AbstractUnArchiver extends AbstractLogEnabled implements UnArchiver, FinalizerEnabled {

    private boolean overwrite = true;
    private boolean ignorePermissions = false;

    // other methods

    protected void extractFile(final File srcF, final File dir, final InputStream compressedInputStream, final String entryName, final Date entryDate, final boolean isDirectory, final Integer mode, String symlinkDestination) throws IOException, ArchiverException {

        // Resolve the target file path
        final File f = FileUtils.resolveFile(dir, entryName);

        // Canonicalize the target directory and the resolved file path
        final Path canonicalDirPath = dir.getCanonicalFile().toPath();
        final Path canonicalDestPath = f.getCanonicalFile().toPath();

        // Ensure the resolved file path is within the target directory
        if (!canonicalDestPath.startsWith(canonicalDirPath)) {
            throw new ArchiverException("Entry is outside of the target directory (" + entryName + ")");
        }

        // Prevent symlink attacks: if the target is a symlink and we are not creating a symlink, abort
        if (StringUtils.isEmpty(symlinkDestination) && Files.isSymbolicLink(canonicalDestPath)) {
            throw new ArchiverException("Attempted to overwrite a symbolic link (" + entryName + ")");
        }

        try {
            // Skip extraction if overwrite is disabled and the file already exists with newer timestamp
            if (!isOverwrite() && f.exists() && (f.lastModified() >= entryDate.getTime())) {
                return;
            }

            // Create parent directories if necessary
            final File dirF = f.getParentFile();
            if (dirF != null) {
                dirF.mkdirs();
            }

            // Handle symlink creation
            if (!StringUtils.isEmpty(symlinkDestination)) {
                SymlinkUtils.createSymbolicLink(f, new File(symlinkDestination));
            } else if (isDirectory) {
                // Create directory
                f.mkdirs();
            } else {
                // Extract file contents
                try (OutputStream out = new FileOutputStream(f)) {
                    IOUtil.copy(compressedInputStream, out);
                }
            }

            // Set last modified time
            f.setLastModified(entryDate.getTime());

            // Apply permissions if required
            if (!isIgnorePermissions() && mode != null && !isDirectory) {
                ArchiveEntryUtils.chmod(f, mode);
            }
        } catch (final FileNotFoundException ex) {
            getLogger().warn("Unable to expand to file " + f.getPath());
        }
    }

    // other methods

    @Override
    public boolean isIgnorePermissions()
    {
        return ignorePermissions;
    }

    @Override
    public boolean isOverwrite()
    {
        return overwrite;
    }

}
