import javax.ws.rs.ext.RuntimeDelegate;
import java.util.regex.Pattern;

public class MediaTypeHeaderDelegate implements RuntimeDelegate.HeaderDelegate<javax.ws.rs.core.MediaType>
{
   // other methods

   /**
    * Validates a media type component (major or subtype) according to RFC 7231.
    *
    * @param str the component string to validate
    * @return {@code true} if the component is valid, {@code false} otherwise
    */
   protected static boolean isValid(String str) {
      if (str == null || str.isEmpty()) {
         return false;
      }

      /*
       * RFC 7231 defines a media type component as a token. A token consists of one or more
       * characters from the set: ALPHA / DIGIT / "!" / "#" / "$" / "&" / "'" / "*" /
       * "+" / "-" / "." / "^" / "_" / "`" / "|" / "~".
       *
       * The following regex matches exactly those characters. It also rejects control
       * characters, whitespace, and any other punctuation that could be used for header
       * injection.
       */
      final Pattern TOKEN_PATTERN = Pattern.compile("^[!#$%&'*+-.^_`|~A-Za-z0-9]+$");

      return TOKEN_PATTERN.matcher(str).matches();
   }

   // other methods

}
