private int extend(int v, final int t) {
    // Validate input parameters to prevent misuse or infinite loops.
    if (t <= 0 || t > 31) { // t must be within a reasonable range for 32-bit ints
        throw new IllegalArgumentException("Parameter t out of valid range: " + t);
    }
    if (v < 0) {
        throw new IllegalArgumentException("Parameter v must be non-negative: " + v);
    }

    // Compute vt once outside the loop; vt represents the threshold value.
    int vt = 1 << (t - 1);

    // Ensure vt is positive and does not overflow.
    if (vt <= 0) {
        throw new IllegalArgumentException("Computed vt is invalid: " + vt);
    }

    // Use a loop that guarantees termination by adding vt until v >= vt.
    // Since vt is constant, the loop will terminate after at most one iteration.
    while (v < vt) {
        v += vt;
    }

    return v;
