import java.nio.ByteBuffer;
import java.nio.CharBuffer;
import java.nio.charset.CharsetEncoder;
import java.nio.charset.CoderResult;

class NioZipEncoding implements ZipEncoding, CharsetAccessor {

    // other methods

    @Override
    public ByteBuffer encode(final String name) {
        final CharsetEncoder enc = newEncoder();
        final CharBuffer cb = CharBuffer.wrap(name);
        CharBuffer tmp = null;
        ByteBuffer out = ByteBuffer.allocate(estimateInitialBufferSize(enc, cb.remaining()));

        // Track progress to avoid infinite loops
        int lastCbPosition = -1;
        int retryLimit = 10; // maximum retries for unmappable/malformed sequences
        int retryCount = 0;

        while (cb.remaining() > 0) {
            final CoderResult res = enc.encode(cb, out, false);

            // Detect lack of progress
            if (cb.position() == lastCbPosition) {
                if (++retryCount > retryLimit) {
                    // Give up after too many retries
                    throw new IllegalArgumentException("Encoding failed due to repeated unmappable/malformed input");
                }
            } else {
                retryCount = 0;
                lastCbPosition = cb.position();
            }

            if (res.isUnmappable() || res.isMalformed()) {
                // Ensure buffer has enough space for surrogate handling
                int spaceForSurrogate = estimateIncrementalEncodingSize(enc, 6 * res.length());
                if (spaceForSurrogate > out.remaining()) {
                    int charCount = 0;
                    for (int i = cb.position(); i < cb.limit(); i++) {
                        charCount += !enc.canEncode(cb.get(i)) ? 6 : 1;
                    }
                    int totalExtraSpace = estimateIncrementalEncodingSize(enc, charCount);
                    out = ZipEncodingHelper.growBufferBy(out, totalExtraSpace - out.remaining());
                }

                if (tmp == null) {
                    tmp = CharBuffer.allocate(6);
                }

                // Encode each problematic character individually
                for (int i = 0; i < res.length(); ++i) {
                    out = encodeFully(enc, encodeSurrogate(tmp, cb.get()), out);
                }
            } else if (res.isOverflow()) {
                int increment = estimateIncrementalEncodingSize(enc, cb.remaining());
                out = ZipEncodingHelper.growBufferBy(out, increment);
            } else if (res.isError()) {
                // Handle unexpected errors
                res.throwException();
            }
        }

        // Final flush
        final CoderResult finalRes = enc.encode(cb, out, true);
        if (finalRes.isError()) {
            finalRes.throwException();
        }

        out.limit(out.position());
        out.rewind();
        return out;
    }

    /**
     * Estimate the size needed for remaining characters
     *
     * @param enc       encoder to use for estimates
     * @param charCount number of characters remaining
     * @return estimated size in bytes.
     */
    private static int estimateIncrementalEncodingSize(CharsetEncoder enc, int charCount) {
        // Implementation uses average bytes per character
        float avgBytesPerChar = enc.averageBytesPerChar();
        return Math.max(1, (int) Math.ceil(avgBytesPerChar * charCount));
    }

    private static ByteBuffer encodeFully(CharsetEncoder enc, CharBuffer cb, ByteBuffer out) {
        while (cb.hasRemaining()) {
            CoderResult cr = enc.encode(cb, out, true);
            if (cr.isOverflow()) {
                out = ZipEncodingHelper.growBufferBy(out, estimateIncrementalEncodingSize(enc, cb.remaining()));
            } else if (cr.isError()) {
                cr.throwException();
            }
        }
        return out;
    }

    private static CharBuffer encodeSurrogate(CharBuffer cb, char c) {
        cb.clear();
        if (Character.isHighSurrogate(c) || Character.isLowSurrogate(c)) {
            cb.put(c);
        } else {
            // Replace non-surrogate with replacement character
            cb.put(Character.toChars(0xFFFD)[0]);
        }
        cb.flip();
        return cb;
    }

